const PACKED = "";

let cache: Set<string> | null = null;
export function isAllowed(word: string): boolean {
  if (!cache) {
    cache = new Set(ANSWERS);
    for (let i = 0; i < PACKED.length; i += 5) cache.add(PACKED.slice(i, i + 5));
  }
  return cache.has(word);
}
